export const SEED_QUESTIONS: Omit<Question, "id">[] = [
  { order: 1, text: "Kategori 1 - Lokasi 1.1 SKOR - Unit pengolahan berlokasi di area yang bebas dari bau tak sedap, asap, debu, atau kontaminan dan berada di area yang tidak rawan banjir." },
  { order: 2, text: "Kategori 2 - Jalan dan area yang digunakan kendaraan  2.1 SKOR - Memiliki permukaan keras dengan dilengkapi sistem drainase yang memadai dan terdapat tata cara pembersihan." },
  { order: 3, text: "Kategori 3 - Bangunan dan fasilitas 3.1 SKOR - Memiliki konstruksi yang kokoh dan terawat serta terbuat dari bahan yang tidak mencemari pangan" },
  { order: 4, text: "3.2 SKOR - Tersedia ruang kerja yang memadai" },
  { order: 5, text: "3.3 SKOR - Desain bangunan dan fasilitas mudah dibersihkan dan dipantau kebersihannya" },
  { order: 6, text: "3.4 SKOR - Bangungan dan fasilitas didesain untuk mencegah masuknya hama dan kontaminan" },
  { order: 7, text: "3.5 SKOR - Bangunan dan fasilitas harus dirancang untuk mencegah kontaminasi silang Copy" },
  { order: 8, text: "3.6 SKOR - Bangunan dan fasilitas dirancang untuk memudahkan pembersihan, pengaturan alur produksi dengan pemantauan suhu pada setiap tahapan." },
  { order: 9, text: "3.7.1 SKOR - Lantai harus tahan air, anti-slip, tanpa celah, mudah dicuci, dan didesinfeksi." },
  { order: 10, text: "3.7.2 SKOR - Dinding yang sebaiknya berwarna cerah harus tahan air, halus, tanpa celah, mudah dicuci dan didesinfeksi. Sudut dinding dengan lantai atau langit-langit sebaiknya didesain agar mudah dibersihkan." },
  { order: 11, text: "3.7.3 SKOR - Langit-langit harus dirancang untuk mencegah kondensasi dan pengelupasan, , penumpukan kotoran, pengelupasan, kemudahan pembersihan." },
  { order: 12, text: "3.7.4 SKOR - Jendela dan lubang udara harus dirancang mencegah penumpukan kotoran, ditutup kawat anti serangga yang mudah dilepas untuk pembersihan." },
  { order: 13, text: "3.7.5 SKOR - Pintu harus halus, tahan air, menutup sendiri, dan rapat." },
  { order: 14, text: "3.7.6 SKOR - Tangga, lift, dan struktur tambahan harus dirancang untuk mencegah kontaminasi pangan. Saluran harus mudah diperiksa dan dibersihkan." },
  { order: 15, text: "3.8 SKOR - Semua struktur bagian atas (overhead) dan sambungan (fittings) di area penanganan pangan harus dipasang (dapat dilakukan insulasi) untuk mencegah kontaminasi langsung atau tidak langsung dari kondensasi atau tetesan." },
  { order: 16, text: "3.9 SKOR - Ruang istirahat, toilet, dan area penyimpanan atau pemeliharaan hewan harus terpisah dan tidak memiliki akses langsung ke area penanganan pangan" },
  { order: 17, text: "3.10 SKOR - Jika diperlukan, unit pengolahan dirancang kemudahan pengendalian akses" },
  { order: 18, text: "3.11 SKOR - Material yang sulit dibersihkan dan didesinfeksi, seperti kayu, sebaiknya dihindari kecuali jika dipastikan tidak menyebabkan kontaminasi" },
  { order: 19, text: "3.12.1 SKOR - Pasokan air yang terlindung dari kontaminasi harus cukup, dengan tekanan yang memadai dan suhu yang sesuai." },
  { order: 20, text: "3.12.2 SKOR - Terdapat sistem yang memastikan kecukupan pasokan air panas layak minum tetap mencukupi." },
  { order: 21, text: "3.12.3 SKOR - Es harus dibuat dari air layak minum serta diproduksi, ditangani, dan disimpan dengan cara yang mencegah kontaminasi" },
  { order: 22, text: "3.12.4 SKOR - Uap yang bersentuhan langsung dengan pangan atau permukaannya harus bebas dari zat berbahaya" },
  { order: 23, text: "3.12.5 SKOR - Air yang tidak layak minum untuk uap, pendinginan, pemadam kebakaran, dan keperluan lain yang tidak terkait pangan harus dialirkan melalui saluran terpisah dengan penandaan warna." },
  { order: 24, text: "3.13.1 SKOR - - Sistem pembuangan limbah cair dan padat harus efisien serta dipelihara dan diperbaiki secara rutin." },
  { order: 25, text: "3.13.2 SKOR - - Selokan sebagai saluran pembuangan limbah harus tertutup dan dirancang untuk mencegah kontaminasi pada pasokan air layak minum." },
  { order: 26, text: "3.14.1 SKOR - Unit pengolahan harus memiliki sistem pendingin dan/atau pembeku yang cukup untuk menyimpan bahan mentah pada suhu yang sesuai sesuai dengan persyaratan di 7.1.4 dan 7.1" },
  { order: 27, text: "3.14.2 SKOR - Unit pengolahan harus memiliki sistem pendingin dan/atau pembeku, atau freeze tunnel yang dapat mendinginkan atau membekukan sesuai dengan persyaratan di 7.7 dan 7.8" },
  { order: 28, text: "3.14.3 SKOR - Unit pengolahan harus memiliki sistem pendingin dan/atau pembeku, atau peralatan penyimpanan dingin dan beku untuk pangan olahan, sesuai dengan kapasitas produksi harian, agar memenuhi persyaratan di 7.7 dan 7.8." },
  { order: 29, text: "3.14.4 SKOR - Semua ruang pendingin harus dilengkapi dengan alat pengukur suhu, dan jika memungkinkan,sebaiknya menggunakan alat perekam suhu dan alarm suhu." },
  { order: 30, text: "3.15.1 SKOR - Berlokasi dekat dengan unit pengolahan dengan pembuangan limbah yang higienis." },
  { order: 31, text: "3.15.2 SKOR - Memiliki pencahayaan yang baik, ventilasi, dan pengatur suhu yang memadai serta tidak langsung terbuka ke area penanganan pangan." },
  { order: 32, text: "3.15.3 SKOR - Dilengkapi fasilitas cuci tangan lengkap dan higienis, serta pengingat mencuci tangan setelah menggunakan toilet." },
  { order: 33, text: "3.15.4 SKOR - Keran tanpa sentuhan tangan lebih disarankan." },
  { order: 34, text: "3.16.1 SKOR - Jika diperlukan dalam ruang proses, harus tersedia fasilitas cuci sebaiknya tanpa sentuhan tangan, disinfeksi dan pengering tangan yang memadai dan mudah diakses." },
  { order: 35, text: "3.16.2 SKOR - Air hangat atau panas, air dingin, serta perlengkapan pembersih dan pengeringan tangan yang sesuai harus tersedia." },
  { order: 36, text: "3.16.3 SKOR - Pipa pembuangan tertutup yang terhubung ke saluran air." },
  { order: 37, text: "3.17 SKOR - Jika diperlukan, harus tersedia fasilitas untuk pembersihan dan desinfeksi peralatan kerja yang terbuat dari material tahan korosi, mudah dibersihkan, dan dilengkapi dengan pasokan air yang memadai." },
  { order: 38, text: "3.18.1 SKOR - Unit pengolahan harus memiliki pencahayaan alami atau buatan yang memadai." },
  { order: 39, text: "3.18.2 SKOR - Jika diperlukan, pencahayaan harus memiliki intensitas minimal: - 540 lux (50 foot candles) di area persiapan dan inspeksi pangan. - 220 lux (20 foot candles) di ruang kerja. - 110 lux (10 foot candles) di area lainnya." },
  { order: 40, text: "3.18.3 SKOR - Bola lampu dan peralatan pencahayaan di atas bahan pangan harus aman dan terlindungi." },
  { order: 41, text: "3.19.1 SKOR - Ventilasi harus memadai" },
  { order: 42, text: "3.19.2 SKOR - Aliran udara di area industri harus mengarah dari area bersih ke area kotor, harus dilengkapi dengan kawat kasa atau penutup dari bahan tidak korosif." },
  { order: 43, text: "3.20 SKOR - Tersedia fasilitas untuk penyimpanan limbah dan bahan yang tidak bisa dimakan sebelum dibuang dari unit pengolahan dan didesain untuk mencegah akses hama dan kontaminasi." },
  { order: 44, text: "Kategori 4 - Peralatan dan perkakas 4.1.1 SKOR - terbuat dari bahan yang tidak beracun, bau atau rasa, serta kedap air, tahan korosi dan tahan terhadap pembersihan dan desinfeksi berulang." },
  { order: 45, text: "4,1.2 SKOR - Permukaan halus dan bebas dari lubang dan celah." },
  { order: 46, text: "4.2.1 SKOR - Semua peralatan dan perkakas yang mudah diakses, didesain dan dibangun untuk mencegah kontaminasi dan mempermudah pembersihan dan desinfeksi yang menyeluruh" },
  { order: 47, text: "4.2.2 SKOR - Wadah sekali pakai yang tertutup untuk bahan yang tidak bisa dimakan dan limbah tahan bocor, terbuat dari metal atau bahan tahan air yang sesuai dan mudah dibersihkan." },
  { order: 48, text: "4.3 SKOR - Peralatan dan perkakas yang digunakan untuk bahan yang tidak bisa dimakan atau limbah diidentifikasi dan tidak digunakan untuk produk yang bisa dimakan" },
  { order: 49, text: "4.4 SKOR - Peralatan yang mudah dipindahkan seperti sendok, pengaduk, panci dan wajan, dan lain-lain terlindungi dari kontaminasi." },
  { order: 50, text: "Kategori Pemeliharaan 5.1 SKOR - Bangunan, peralatan, perkakas dan semua fasilitas fisik lain dari unit pengolahan, termasuk drainase, dipelihara terus menerus dalam kondisi yang baik." },
  { order: 51, text: "5.2.1 SKOR - Pembersihan disinfeksi sebaiknya memenuhi persyaratan dalam kode ini." },
  { order: 52, text: "5.2.2 SKOR - Pembersihan semua peralatan dan perkakas dilakukan sesuai frekuensi yang dibutuhkan dan jika diperlukan dilakukan desinfeksi." },
  { order: 53, text: "5.2.3 SKOR -  Pembersihan atau desinfeksi ruangan mencakup pemantauan residu dari bahan yang mungkin kontak dengan makanan, peralatan atau perkakas dengan air pencucian (wash water), detergen atau desinfektan yang sudah diizinkan.- Cairan pembersih sebaiknya disimpan dalam wadah berlabel non-food yang cukup jelas." },
  { order: 54, text: "5.2.4 SKOR - Setelah pekerjaan selesai, lantai, termasuk drainase, struktur tambahan dan dinding pada area penanganan pangan (food handling) sebaiknya dibersihkan secara menyeluruh." },
  { order: 55, text: "5.2.5 SKOR - Peralatan pemeliharaan, peralatan kebersihan dan bahan kimia pembersih dijaga dan disimpan sehingga tidak menjadi sumber kontaminan" },
  { order: 56, text: "5.2.6 SKOR - Ruang ganti (changing facilities) dan toilet dijaga tetap bersih sepanjang waktu." },
  { order: 57, text: "5.2.7 SKOR - Jalan dan halaman sekitar tempat penyajian dijaga tetap bersih" },
  { order: 58, text: "5.3.1 SKOR - Terdapat prosedur tertulis pembersihan dan desinfeksi" },
  { order: 59, text: "5.3.2 SKOR - Terdapat seorang yang bertanggung jawab terhadap kebersihan unit pengolahan yang memiliki pemahaman kontaminasi dan bahaya yang terkandung serta teknik kebersihan." },
  { order: 60, text: "5.4.1 SKOR - Produk samping (by-products) dan limbah dikumpulkan dalam kantong tahan bocor yang tertutup sekali pakai atau wadah berlabel jelas “dipakai ulang” (reusable)." },
  { order: 61, text: "5.4.2 SKOR - Wadah reusable sebaiknya dibersihkan dan didesinfeksi setiap kali dibawa masuk kembali ke dapur." },
  { order: 62, text: "5.4.3 SKOR - Tempat sampah sebaiknya dijaga tetap berada pada area tertutup dan terpisah dari area penanganan pangan (food handling), terlindung dari serangga dan hewan pengerat dan mudah untuk dibersihkan dan didesinfeksi." },
  { order: 63, text: "5.4.4 SKOR - Karton dan pembungkus sebaiknya, segera setelah kosong, dipindahkan dengan cara yang sama dengan penanganan bahan limbah." },
  { order: 64, text: "5.4.5 SKOR - Bukaan saluran pembuangan sebaiknya dibersihkan dan didesinfeksi setiap hari" },
  { order: 65, text: "5.5 SKOR - Hewan apapun yang dapat berbahaya bagi kesehatan sebaiknya disingkirkan dari unit pengolahan." },
  { order: 66, text: "5.6.1 SKOR - Terdapat program yang efektif dan berkelanjutan untuk pengendalian hama yang diperiksa secara rutin" },
  { order: 67, text: "5.6.2 SKOR -  Jika hama ditemukan masuk ke dalam unit pengolahan, segera dilakukan langkah pemberantasan. - Langkah pengendalian hama termasuk treatment dengan bahan kimia, fisik atau biologi hanya dilakukan oleh personel yang memiliki pemahaman mengenai bahaya potensial bagi kesehatan termasuk residu." },
  { order: 68, text: "5.6.3 SKOR -  Pestisida hanya digunakan jika tindakan pencegahan lain tidak bisa dilakukan secara efektif. - Sebelum pestisida diaplikasikan semua pangan, peralatan dan perkakas perlu dengan hati hati dijaga dari kontaminasi dan dipastikan residu dihilangkan sebelum digunakan kembali" },
  { order: 69, text: "5.7.1 SKOR -  Pestisida atau bahan berbahaya diberi label yang jelas dengan peringatan tentang penggunaan dan toksisitasnya. - Penyimpanan pada ruangan atau kabinet terkunci spesifik dan ditangani hanya oleh personel yang memiliki otoritas dan telah dilatih dengan baik.- Wadah bekas pangan dan wadah untuk menangani pangan tidak digunakan untuk mengukur, mengencerkan, mengeluarkan atau menyimpan pestisida atau bahan berbahaya lain." },
  { order: 70, text: "5.7.2 SKOR - Kecuali jika diperlukan untuk tujuan higienis atau proses sebaiknya tidak ada bahan yang digunakan atau disimpan pada area penanganan pangan (food handling) yang dapat mengkontaminasi pangan." },
  { order: 71, text: "5.8 SKOR - Barang pribadi dan pakaian sebaiknya tidak disimpan di area penanganan pangan (food handling)." },
  { order: 72, text: "Kategori 6.1 - Pelatihan Higiene 6.1 SKOR - Manajer unit pengolahan menjadwalkan pelatihan yang memadai dan berkelanjutan untuk setiap personil tentang penanganan pangan yang higienis dan hygiene personal" },
  { order: 73, text: "Kategori 6.2 - Pemeriksaan kesehatan 6.2 SKOR - Personil yang akan kontak dengan pangan perlu melakukan pemeriksaan kesehatan sebelum dipekerjakan dan jika terdapat indikasi klinis maupun epidemiologis" },
  { order: 74, text: "Kategori 6.3 - Penyakit menular 6.3.1 SKOR - Manajemen harus memastikan bahwa tidak ada orang yang diketahui atau diduga menderita atau membawa penyakit yang mungkin dapat ditularkan di dalam area penanganan pangan" },
  { order: 75, text: "6.3.2 SKOR - Setiap orang yang tertular harus melaporkan kepada manajemen bahwa dirinya sedang sakit" },
  { order: 76, text: "Kategori Cedera 6.4.1 SKOR - Setiap orang yang tersayat atau terluka tidak melanjutkan pekerjaannya dalam penanganan pangan" },
  { order: 77, text: "6.4.2 SKOR - Tersedianya fasilitas pertolongan pertama yang memadai" },
  { order: 78, text: "Kategori Pencucian tangan 6.5.1 SKOR - Setiap orang yang bekerja pada area penanganan pangan (food handling) sebaiknya sering mencuci tangan saat sedang bertugas" },
  { order: 79, text: "6.5.2 SKOR - Tersedianya peringatan untuk mencuci tangan dan dilakukan pengawasan yang memadai." },
  { order: 80, text: "Kategori 6.6 - Kebersihan personal 6.6.1 SKOR - Setiap orang yang bertugas pada area penanganan pangan (food handling) harus menjaga dan memiliki kebersihan personal" },
  { order: 81, text: "6.6.2 SKOR - Selama bekerja mengenakan pakaian pelindung yang sesuai" },
  { order: 82, text: "6.6.3 SKOR - Celemek (aprons) dan perlengkapan sejenis lainnya sebaiknya tidak dicuci dan/atau dikeringkan dalam area penanganan atau penyiapan makanan." },
  { order: 83, text: "6.6.4 SKOR - Personel tidak menggunakan perhiasan selama ketika bekerja dalam penanganan pangan (food handling)." },
  { order: 84, text: "Kategori 6.7 - Perilaku personal 6.7 SKOR - Segala perilaku yang dapat menyebabkan kontaminasi pangan seperti makan, merokok, mengunyah atau tindakan tidak higienis seperti meludah dilarang dalam area penanganan pangan (food handling)." },
  { order: 85, text: "Kategori 6.8 - Sarung Tangan 6.8 SKOR - Sarung tangan sebaiknya dipelihara dalam kondisi yang baik (sound), bersih dan saniter." },
  { order: 86, text: "Kategori 6.9 - Pengunjung 6.9 SKOR - Pengunjung menggunakan pakaian pelindung di area penanganan pangan" },
  { order: 87, text: "Kategori 6.10 - Pengawasan 6.10 SKOR - Terdapat personel kompeten yang bertanggung jawab untuk memastikan semua personel mematuhi semua persyaratan yang termasuk pada paragraf 6.1 hingga 6.9" },
  { order: 88, text: "Kategori 7.1 - Pesyaratan bahan baku 7.1.1 SKOR - Bahan baku tidaki mengandung parasit, mikroorganisme atau racun,- Bahan yang sudah rusak atau benda asing yang tidak dapat dihilangkan atau dikurangi ke batas yang dapat diterima melalui prosedur penyortiran, dan/atau penyiapan, atau pemrosesan yang biasa dilakukan di tempat pengolahan." },
  { order: 89, text: "7.1.2 SKOR - Bahan baku atau ingredient diperiksa, termasuk kebersihannya sebelum proses memasak dan jika diperlukan uji laboratorium dilakukan." },
  { order: 90, text: "7.1.3 SKOR - Bahan baku dan ingredien yang disimpan pada tempat yang sesuai untuk mencegah kontaminasi - Stok bahan baku dan ingredien sebaiknya dipasok secara berkala, jumlah wajar dan teratur." },
  { order: 91, text: "7.1.4 SKOR - Bahan baku yang berasal dari hewani, bila diperlukan, dapat disimpan dalam lemari pendingin dengan suhu 1 hingga 4 C. - Bahan baku lain yang membutuhkan pendinginan, sebaiknya disimpan suhu rendah sesuai persyaratan mutu." },
  { order: 92, text: "Kategori 7.2 - Pencegahan kontaminasi silang 7.2.1 SKOR - Upaya efektif untuk mencegah kontaminasi pangan matang dan pangan matang dingin/beku (cooked and precooked foods). - Bahan baku sebaiknya dipisahkan secara efektif dari pangan matang dan pangan matang dingin/beku (cooked and precooked foods)." },
  { order: 93, text: "7.2.2 SKOR - Orang yang menangani bahan baku atau produk semi-proses yang dapat mengkontaminasi produk akhir berbeda dengan produk akhir. Kecuali personil tersebut - Orang yang menangani bahan baku atau produk semi-proses yang dapat mengkontaminasi produk akhir sebaiknya tidak bersinggungan dengan produk akhir manapun kecuali sampai orang tersebut melepaskan semua pakaian pelindung yang dikenakan selama menangani bahan baku atau produk setengah jadi (semi-processed) yang telah kontak langsung atau telah dikotori oleh bahan baku atau produk semi-proses, dan telah berganti ke pakaian pelindung yang bersih" },
  { order: 94, text: "7.2.3 SKOR - Tangan sebaiknya dicuci secara menyeluruh diantara tahap-tahap yang berbeda dalam proses penanganan produk" },
  { order: 95, text: "7.2.4 SKOR - Produk mentah yang berpotensi bahaya sebaiknya diproses pada ruangan terpisah, atau pada area yang dipisahkan oleh pembatas, dari area yang digunakan untuk menyiapkan pangan siap saji." },
  { order: 96, text: "7.2.5 SKOR - Semua peralatan yang kontak dengan bahan mentah atau bahan terkontaminasi sebaiknya dibersihkan dan didisinfeksi secara menyeluruh sebelum digunakan untuk kontak dengan pangan matang dan pangan matang dingin/beku (cooked and precooked foods). - Ada peralatan tersendiri yang terpisah untuk menangani bahan mentah serta pangan matang dan pangan matang dingin/beku (cooked and precooked foods), khususnya perkakas untuk mengiris dan mencincang." },
  { order: 97, text: "Kategori 7.3 - Penggunaan air pada pengolahan pangan 7.3 SKOR - Buah dan sayuran mentah yang akan digunakan pada pangan sebaiknya dicuci secara menyeluruh dengan menggunakan air layak minum (potable water) sebelum ditambahkan ke dalam pangan." },
  { order: 98, text: "Kategori 7.4 - Pelelehan (thawing) 7.4.1 SKOR - Produk beku, terutama sayuran beku dapat dimasak tanpa pelelehan (thawing). Namun, potongan besar daging atau potongan besar karkas unggas seringkali membutuhkan pelelehan (thawing) sebelum dimasak" },
  { order: 99, text: "7.4.2 SKOR - Ketika thawing dilakukan sebagai kegiatan terpisah dari memasak, kegiatan ini sebaiknya hanya dilakukan di: i. Lemari pendingin atau lemari yang dibuat khusus untuk thawing yang diatur pada suhu 4C atau lebih rendah.atauii. Air layak minum (potable water) mengalir yang dijaga pada suhu tidak lebih dari 21C pada periode tidak lebih dari 4 jam.atau iii. Oven microwave komersial hanya jika pangan akan segera dipindahkan ke peralatan memasak konvensional sebagai bagian dari proses memasak yang berkelanjutan atau ketika seluruh proses memasak, tanpa terinterupsi, dilakukan pada oven microwave." },
  { order: 100, text: "Kategori 7.5 - Proses memasak 7.5 SKOR - Lemak dan minyak sebaiknya disaring sebelum setiap kegiatan menggoreng untuk menghilangkan partikel dari pangan dengan filter yang disesuaikan untuk tujuan ini. (Deep-fryer sebaiknya dilengkapi dengan keran untuk mengosongkan minyak dari dasar). - Kualitas minyak dan lemak sebaiknya diperiksa secara rutin terkait bau, rasa dan warna asap, dan jika diperlukan, didiganti. Jika kualitas diragukan, minyak untuk menggoreng dapat diperiksa dengan menggunakan peralatan uji komersial.  Jika hasil dari pengujian ini positif, sampel dapat diperiksa lebih lanjut untuk titik asap, asam lemak bebas dan khususnya senyawa polar." },
  { order: 101, text: "7.5.1 SKOR - Waktu dan suhu memasak sebaiknya cukup untuk memastikan matinya mikroorganisme patogenik bukan pembentuk spora." },
  { order: 102, text: "7.5.2 SKOR - Ketika produk yang dibakar, dipanggang, ditumis, digoreng, diblansir, direbus (poached, boiled), atau dimasak tidak dimaksudkan untuk dikonsumsi pada hari yang sama saat produk tersebut disiapkan, proses memasak sebaiknya diikuti dengan pendinginan secepat mungkin." },
  { order: 103, text: "Kategori 7.6 – Proses pembagian (portioning) 7.6.1 SKOR - Kondisi higiene yang ketat sebaiknya diaplikasikan (diterapkan) pada tahap proses ini. Proses pembagian (portioning) sebaiknya diselesaikan dalam periode waktu praktis minimum yang sebaiknya tidak melebihi 30 menit untuk setiap produk yang didinginkan." },
  { order: 104, text: "7.6.2 SKOR - Hanya wadah yang sudah dibersihkan dan didisinfeksikan dengan baik yang sebaiknya digunakan." },
  { order: 105, text: "7.6.3 SKOR - Wadah dengan tutup lebih disukai sehingga pangan terlindungi dari kontaminasi." },
  { order: 106, text: "7.6.4 SKOR - Dalam sistem skala besar dimana proses pembagian (portioning) makanan matang dingin tidak bisa dilakukan dalam 30 menit, pembagian sebaiknya dilakukan pada area terpisah dengan suhu ambien 15 C. - Suhu pangan sebaiknya dipantau menggunakan termometer makanan (probes). - Produk sebaiknya disajikan segera atau ditempatkan pada lemari pendingin pada suhu 4 C." },
  { order: 107, text: "Kategori 7.7 - Proses pendinginan dan kondisi penyimpanan pangan dingin 7.7.1 SKOR - Segera setelah penyiapan, pendinginan sebaiknya dilakukan secepat dan seefisien mungkin." },
  { order: 108, text: "7.7.2 SKOR - Suhu di pusat produk pangan sebaiknya diturunkan dari 60 C menjadi 10 C dalam waktu kurang dari dua jam kemudian produk sebaiknya segera disimpan pada suhu 4 C." },
  { order: 109, text: "7.7.3 SKOR - Segera setelah pendinginan selesai, produk sebaiknya dimasukkan ke dalam lemari pendingin. - Suhu sebaiknya tidak melebihi +4 C pada setiap bagian produk dan sebaiknya dijaga hingga penggunaan akhir. - Pengawasan terhadap suhu penyimpanan ini diperlukan dilakukan secara teratur." },
  { order: 110, text: "7.7.4 SKOR - Periode penyimpanan antara penyiapan pangan dingin sampai dengan konsumsi sebaiknya tidak lebih dari lima hari sejak hari pemasakan sampai hari dikonsumsi." },
  { order: 111, text: "Kategori 7.8 - Proses pembekuan dan kondisi penyimpanan pangan beku 7.8.1 SKOR - Segera setelah penyiapan, pembekuan sebaiknya dilakukan secepat dan seefisien mungkin." },
  { order: 112, text: "7.8.2 SKOR -  Pangan matang beku sebaiknya dipertahankan pada suhu -18 C atau lebih rendah. - Pemantauan secara teratur pada suhu penyimpanan penting dilakukan." },
  { order: 113, text: "7.8.3 SKOR - Pangan matang beku dapat disimpan pada suhu 4 C atau lebih rendah namun tidak lebih dari lima hari dan sebaiknya tidak dibekukan kembali." },
  { order: 114, text: "Kategori 7.9 - Pengangkutan 7.9.1 SKOR - Persyaratan higienis juga diaplikasikan dalam kendaraan yang mengangkut pangan matang dan pangan matang dingin/beku (cooked and precooked foods)." },
  { order: 115, text: "7.9.2 SKOR - Selama pengangkutan, pangan sebaiknya dilindungi dari debu dan polutan lainnya." },
  { order: 116, text: "7.9.3 SKOR - Kendaraan dan/atau wadah yang dimaksudkan untuk mengangkut pangan yang dipanaskan sebaiknya didesain untuk menjaga pangan pada suhu minimum 60 C ." },
  { order: 117, text: "7.9.4 SKOR - Kendaraan dan/atau kontainer yang ditujukan untuk mengangkut pangan matang dingin sebaiknya disesuaikan kondisinya.- Kendaraan pengangkut didesain sedemikian rupa untuk mempertahankan suhu pangan yang telah dingin dan bukan untuk mendinginkan pangan tersebut. - Suhu pangan matang dingin sebaiknya dijaga pada suhu 4 C, tetapi diperbolehkan meningkat menjadi suhu 7 C untuk periode yang pendek selama pengangkutan." },
  { order: 118, text: "7.9.5 SKOR - Kendaraan dan/atau kontainer yang ditujukan untuk mengangkut pangan matang beku sebaiknya disesuaikan kondisinya. - Suhu pangan matang beku sebaiknya dijaga pada - 18 C atau di bawahnya, tetapi diperbolehkan meningkat menjadi suhu -12 C untuk periode yang pendek selama pengangkutan" },
  { order: 119, text: "Kategori 7.10 – Pemanasan kembali dan penyajian 7.10.1 SKOR - Pemanasan kembali pangan sebaiknya dilakukan dengan cepat. - Proses pemanasan kembali harus memadai yaitu suhu minimum 75 C sebaiknya dicapai di bagian tengah pangan dalam waktu satu jam sejak pangan dikeluarkan dari lemari pendingin. - Suhu yang lebih rendah boleh digunakan untuk memanaskan kembali, asalkan kombinasi waktu/suhu yang digunakan setara dalam hal mematikan mikroorganisme pada suhu pemanasan 75 C ." },
  { order: 120, text: "7.10.2 SKOR - Sebaiknya pangan yang dipanaskan kembali dapat diterima konsumen dengan sesegera mungkin dan pada suhu minimum 60 C ." },
  { order: 121, text: "7.10.3 SKOR - Setiap pangan yang tidak dikonsumsi sebaiknya dibuang dan tidak dipanaskan kembali atau tidak dikembalikan ke lemari pendingin atau lemari pembeku." },
  { order: 122, text: "7.10.4 SKOR - Dalam sistem swalayan/layanan prasmanan, penyajian pangan sebaiknya sedemikian rupa sehingga pangan yang dihidangkan terlindungi dari kontaminasi langsung yang dihasilkan dari lingkungan sekitar atau kegiatan konsumen. - Suhu pangan sebaiknya antara di bawah 4 C atau di atas 60 C ." },
  { order: 123, text: "Kategori 7.11 - Identifikasi dan sistem pengendalian mutu 7.11.1 SKOR - Setiap wadah pangan sebaiknya diberi label dengan tanggal produksi, jenis pangan, nama unit pengolahan dan nomor lot." },
  { order: 124, text: "7.11.2 SKOR - Prosedur pengendalian mutu sebaiknya dilaksanakan oleh personel teknis yang kompeten yang memahami prinsip dan praktik higiene pangan, pengetahuan mengenai ketentuan pada persyaratan ini dan personel yang menangani pendekatan HACCP dalam praktik kendali higienis." },
  { order: 125, text: "7.11.3 SKOR - Jika sesuai, untuk tujuan keamanan, contoh uji sedikitnya 150 g dari setiap jenis pangan yang diambil dari setiap lot sebaiknya disimpan dalam wadah steril pada suhu 4 C atau lebih rendah setidaknya tiga hari setelah seluruh lot dikonsumsi. - Beberapa organisme tidak tahan beku sehingga pendinginan contoh uji direkomendasikan sebagai pengganti pembekuan. Contoh uji sebaiknya diambil dari lot pada akhir periode pembagian porsi (portioning). Contoh uji ini sebaiknya disiapkan untuk investigasi dalam hal terdapat kecurigaan adanya penyakit yang berasal dari makanan (food-borne)." },
  { order: 126, text: "7.11.4 SKOR - Otoritas kesehatan akan memerlukan rekaman dari pengolahan SPPG dan skema registrasi yang paling sesuai untuk kepentingannya" },
  { order: 127, text: "Kategori Unit Identifikasi Bahaya: Persyaratan HACCP 8.1.1 SKOR - Apakah SPPG telah menunjuk dan menetapkan personel untuk terlibat dalam Tim HACCP dengan kualifikasi: i. Terdiri dari divisi/bagian yang berbeda ii. Terdiri dari multidisiplin ilmu" },
  { order: 128, text: "8.1.2 SKOR - Apakah SPPG telah mengidentifikasi telah menetapkan ruang lingkup?" },
  { order: 129, text: "8.2 SKOR - Apakah SPPG telah mendeskripsikan produk dengan tepat, yaitu: i. Deskripsi produk telah tersedin untuk setiap jenis kelompok produk ii. Deskripsi produk mencakup komposisi, karakteristik produk (fisika, kimia, biologi), cara pengolahan produk, kemasan akhir/cara penyajian, umur simpan dan penyimpanan." },
  { order: 130, text: "8.3 SKOR - Apakah SPPG telah mengidentifikasi tujuan penggunaan dan pengguna? (hal ini dapat tercantum pada deskripsi produk)" },
  { order: 131, text: "8.4 SKOR - Apakah SPPG telah membuat diagram alir sesuai dengan urutan tahapan produksi, bahan dan kemasan penyajian yang digunakan?" },
  { order: 132, text: "8.5 SKOR - Apakah SPPG telah melakukan konfirmasi diagram alir yang ditetapkan pada butir 8.4 dilapangan dan dilakukan orang yang memiliki pengetahuan tentang proses pengolahan SPPG?" },
  { order: 133, text: "8.6 SKOR - Apakah SPPG telah membuat daftar potensi bahaya (fisika, kimia, biologi), untuk semua tahapan produksi pada diagram alir butir 8.4?" },
  { order: 134, text: "8.7 SKOR - Apakah SPPG telah mengidentifikasi dan menetapkan CCP dengan tepat?" },
  { order: 135, text: "8.8 SKOR - Apakah SPPG telah mengidentifikasi batas kritis yang tervalidasi untuk setiap CCP dengan tepat?" },
  { order: 136, text: "8.9 SKOR - Apakah SPPG telah menetapkan sistem pengendalian untuk setiap CCP?" },
  { order: 137, text: "8.10 SKOR - Apakah SPPG telah menentukan tindakan korektif apabila terjadi penyimpangan telah ditetapkan untuk setiap CCP yang ditetapkan pada butir 8.7?" },
  { order: 138, text: "8.11.1 SKOR - Apakah SPPG telah melakukan validasi terhadap rencana HACCPnya?" },
  { order: 139, text: "8.11.2 SKOR - Apakah SPPG telah menetapkan prosedur verifikasi rencana HACCPnya?" },
  { order: 140, text: "8.12 SKOR - Apakah SPPG telah mendokumentasikan dan merekam seluruh pengendalian HACCPnya?" },
  { order: 141, text: "8.13 SKOR - Apakah SPPG telah memiliki program pelatihan dan melakukan pelatihan penerapan HACCP bagi personel terkait?" },
];
